<?php require '../config.php';admin_required();$slots=$pdo->query('SELECT * FROM parking_slots ORDER BY floor,slot_code')->fetchAll();$total=count($slots);$avail=count(array_filter($slots,fn($x)=>$x['status']==='Available'));$occ=count(array_filter($slots,fn($x)=>$x['status']==='Occupied'));$drivers=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$revenue=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM parking_sessions')->fetchColumn();$recent=$pdo->query('SELECT ps.*,u.name,s.slot_code FROM parking_sessions ps JOIN users u ON u.id=ps.user_id JOIN parking_slots s ON s.id=ps.slot_id ORDER BY ps.id DESC LIMIT 10')->fetchAll();$page_title='Admin Dashboard';require '../includes/header.php';?><section class="dashboard-head"><span class="eyebrow">PARKORA CONTROL CENTER</span><h1>Garage command center.</h1><p class="muted">Monitor live capacity and manage your parking operation.</p></section><?php if(isset($_GET['added'])):?><div class="alert success" style="margin:0 7% 25px">New parking slot added successfully.</div><?php endif;?><div class="stats"><div class="stat"><span class="muted">Total spaces</span><strong><?=$total?></strong></div><div class="stat"><span class="muted">Available</span><strong><?=$avail?></strong></div><div class="stat"><span class="muted">Occupied</span><strong><?=$occ?></strong></div><div class="stat"><span class="muted">Revenue</span><strong>₹<?=number_format($revenue,0)?></strong></div></div><section class="wrap"><div class="head"><div><span class="eyebrow">SPACE MANAGEMENT</span><h2>Parking slots.</h2></div><a class="btn primary" href="add_slot.php">+ Add new slot</a></div><div class="table-card" style="margin:0"><table class="table"><tr><th>Slot</th><th>Floor</th><th>Zone</th><th>Vehicle</th><th>Rate</th><th>Status</th></tr><?php foreach($slots as $s):?><tr><td><b><?=e($s['slot_code'])?></b></td><td><?=e($s['floor'])?></td><td><?=e($s['zone'])?></td><td><?=e($s['vehicle_type'])?></td><td>₹<?=number_format($s['hourly_rate'])?>/hr</td><td><span class="badge <?=strtolower($s['status'])?>"><?=e($s['status'])?></span></td></tr><?php endforeach;?></table></div></section><section class="wrap" style="padding-top:0"><div class="head"><div><span class="eyebrow">LIVE ACTIVITY</span><h2>Recent sessions.</h2></div><div class="muted"><?=$drivers?> registered drivers · <?=($total?round($occ/$total*100):0)?>% occupied</div></div><div class="table-card" style="margin:0"><table class="table"><tr><th>Driver</th><th>Slot</th><th>Vehicle</th><th>Entry</th><th>Status</th><th>Amount</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slot_code'])?></td><td><?=e($r['vehicle_number'])?></td><td><?=date('d M, h:i A',strtotime($r['entry_time']))?></td><td><span class="badge <?=$r['status']==='Active'?'occupied':'available'?>"><?=e($r['status'])?></span></td><td><?=$r['amount']!==null?'₹'.number_format($r['amount'],2):'—'?></td></tr><?php endforeach;?></table></div></section><?php require '../includes/footer.php';?>
